assert.equal((await call(archiveRecorder,'state?yearId='+archiveYear)).status,403,'recorder cannot read archived own-grade students');
assert.equal((await call(archiveRecorder,'students',{yearId:archiveYear,sid:sidB},'DELETE')).status,403);
assert.equal((await call(archiveLead,'event/'+archiveEvent)).status,403);
const historyAfter=(await call(admin,'state?yearId='+archiveYear)).data;
assert.deepEqual(historyAfter.todos,[],'archived semesters never create actionable todos');
assert.deepEqual(historyAfter.students,historyBefore.students);
assert.deepEqual(historyAfter.grades,historyBefore.grades);
assert.deepEqual(historyAfter.events,historyBefore.events);
assert.ok((await call(admin,'years?archived=1')).data.some(y=>y.id===archiveYear));
assert.equal((await call(admin,'photo/'+archivePhoto)).status,200,'administrator can still open archived photos');
assert.equal((await call(admin,'intake',{id:archivedPending},'DELETE')).status,400,'administrator cannot delete archived pending photos');
assert.equal((await call(archiveLead,'intake',{id:archivedPending},'DELETE')).status,403);
assert.equal((await call(admin,'intake/photo/'+archivedPending)).status,200,'archive rejection preserves photo');
assert.equal((await call(admin,'event/'+archiveEvent,{version:1,sid:sidB,score:3},'PATCH')).status,400,'archived grades are read-only even for administrator');
assert.equal((await call(admin,'students',{yearId:archiveYear,sid:sidB},'DELETE')).status,400,'archive protects roster deletion');
assert.equal((await call(admin,'student-grades?yearId='+archiveYear+'&sid='+sidB)).data.events[0].editable,false);
assert.equal((await call(admin,'event/'+archiveEvent,{version:1,sid:sidB,action:'clear'},'PATCH')).status,400,'archive blocks personal score clearing');
assert.equal((await call(admin,'roster',{yearId:archiveYear,rows:[{sid:'20249990001',name:'禁止',college:collegeB,group:'归档组'}]})).status,400);
assert.equal((await call(admin,'years',{id:archiveYear,action:'restore'},'PATCH')).status,200);
assert.ok((await call(lead,'years')).data.some(y=>y.id===archiveYear));
assert.equal((await call(admin,'years',{id:archiveYear,action:'archive'},'PATCH')).status,200);
const renamedCollegeA=`${collegeA}改`;
const renamed=await call(admin,'colleges',{id:full.colleges.find(row=>row.name===collegeA).id,name:renamedCollegeA},'PATCH');
assert.equal(renamed.status,200,'administrator can rename an existing college');
assert.equal((await call(lead,'me')).data.college,renamedCollegeA,'college lead assignment follows the rename');
assert.equal((await call(rec25,'me')).data.college,renamedCollegeA,'recorder assignment follows the rename');
const renamedState=(await call(lead,'state?yearId='+year)).data;
assert.ok(renamedState.students.length>0&&renamedState.students.every(row=>row.college===renamedCollegeA),'college lead retains access to renamed college students');
assert.ok(renamedState.grades.some(row=>row.sid===sid24),'previously recorded grades remain visible after the rename');
assert.deepEqual((await call(lead,'colleges?yearId='+year)).data.map(row=>row.name),[renamedCollegeA]);
const archived=await call(admin,'colleges',{id:renamed.data.id},'DELETE');
assert.equal(archived.status,200);
assert.equal((await call(lead,'event/'+id)).status,200,'archived college history remains readable');
const archivedEvent=(await call(admin,'event/'+id)).data.event;
assert.equal((await call(lead,'event/'+id,{version:archivedEvent.version,sid:sid24,score:81},'PATCH')).status,400,'archived college lead cannot change historical scores');
assert.equal((await call(admin,'event/'+id,{version:archivedEvent.version,sid:sid24,score:81},'PATCH')).status,400,'administrator must restore an archived college before editing');
assert.equal((await call(admin,'colleges',{id:renamed.data.id,action:'restore'},'PATCH')).status,200);
assert.equal((await call(admin,'event/'+id,{version:archivedEvent.version,sid:sid24,score:81},'PATCH')).status,200,'editing resumes after restoring the college');
// Permanent college deletion is admin-only, archived-only and spans school years.
assert.equal((await call(lead,'colleges',{id:renamed.data.id,action:'delete',confirmName:renamedCollegeA},'DELETE')).status,403);
assert.equal((await call(admin,'colleges',{id:renamed.data.id,action:'delete',confirmName:renamedCollegeA},'DELETE')).status,400,'active college cannot be deleted');
assert.equal((await call(admin,'colleges',{id:renamed.data.id},'DELETE')).status,200);
assert.equal((await call(admin,'colleges',{id:renamed.data.id,action:'delete',confirmName:'wrong'},'DELETE')).status,400);
const beforeDeletion=(await call(admin,'state?yearId='+year)).data;
const otherStudents=beforeDeletion.students.filter(row=>row.college===collegeB);
const deleted=await call(admin,'colleges',{id:renamed.data.id,action:'delete',confirmName:renamedCollegeA},'DELETE');
assert.equal(deleted.status,200,JSON.stringify(deleted.data));
assert.equal(deleted.data.deleted,true);
const afterDeletion=(await call(admin,'state?yearId='+year)).data;
assert.ok(!afterDeletion.colleges.some(row=>row.id===renamed.data.id));
assert.ok(!afterDeletion.students.some(row=>row.college===renamedCollegeA));
assert.deepEqual(afterDeletion.students.filter(row=>row.college===collegeB),otherStudents);
assert.ok((await call(admin,'state?yearId='+schoolYear.data.id)).data.students.every(row=>row.college!==renamedCollegeA));
assert.equal((await call(lead,'me')).status,401,'deleted college accounts are disabled');
assert.equal((await call(admin,'event/'+id)).status,400,'deleted activities are gone');
assert.equal((await call(admin,'colleges',{id:renamed.data.id,action:'restore'},'PATCH')).status,400);
const logout=await call(admin,'auth/logout',undefined,'POST');
assert.equal(logout.status,200);
assert.equal(logout.cookie,'gr_session=','logout clears the browser session cookie');
assert.equal((await call(admin,'me')).status,401,'logout revokes the previous session');
console.log('PASS: three-role sharing, cohort isolation in mixed group, photo access, exports, revocation.');
